:root {
  --bg: #ffffff;
  --border: #e4ddd4;
  --accent: #7c5c3e;
  --accent-light: #f5ede3;
  --accent-mid: #c49a72;
  --title-color: #2e1f0f;
  --text-main: #4a3728;
  --text-muted: #9c8472;
  --cover-bg: #7c5c3e;
  --cover-text: #ffffff;
  --progress-bg: #ede4da;
  --progress-fill: #7c5c3e;
  --done-bg: #e4f2e8;
  --done-text: #2e7d4f;
  --reading-bg: #e8f0fb;
  --reading-text: #2c5faa;
  --behind-bg: #fdecea;
  --behind-text: #c0392b;
  --av1: #d4a5c9;
  --av2: #a5c4d4;
  --av3: #a5d4b8;
  --av4: #d4c5a5;
  --footer-bg: #faf7f4;
  --tag-bg: #ede4da;
  --tag-text: #7c5c3e;
}

.tracker {
  background: var(--bg);
  border: 1.5px solid var(--border);
  border-radius: 16px;
  padding: 20px;
  width: 500px;
  max-width: 100%;
}

.tracker-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  text-transform: uppercase;
}

.title {
  font-size: 22px;
  font-weight: 800;
  color: var(--title-color);
  margin: 0;
  line-height: 1.1;
}

.badge {
  background: var(--accent-light);
  color: var(--accent);
  font-size: 12px;
  font-weight: 700;
  padding: 5px 12px;
  border-radius: 20px;
  border: 1px solid var(--accent-mid);
}

.book-main {
  display: flex;
  gap: 14px;
  align-items: center;
  background: var(--accent-light);
  border-radius: 12px;
  padding: 14px;
  margin-bottom: 14px;
}

.book-cover {
  width: 54px;
  height: 72px;
  background: var(--cover-bg);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.cover-initial {
  font-size: 26px;
  font-weight: 900;
  color: var(--cover-text);
}

.book-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.book-meta {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin: 0;
}

.book-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--title-color);
  margin: 0;
  line-height: 1.2;
}

.book-author {
  font-size: 13px;
  color: var(--text-muted);
  margin: 0 0 6px;
}

.progress-bar {
  width: 100%;
  height: 8px;
  background: var(--progress-bg);
  border-radius: 99px;
  overflow: hidden;
}

.progress-fill {
  width: 68%;
  height: 100%;
  background: var(--progress-fill);
  border-radius: 99px;
}

.progress-label {
  font-size: 11px;
  color: var(--text-muted);
  margin: 2px 0 0;
}

.members {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 14px;
}

.member {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg);
}

.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 800;
  color: var(--title-color);
  flex-shrink: 0;
}

.av1 { background: var(--av1); }
.av2 { background: var(--av2); }
.av3 { background: var(--av3); }
.av4 { background: var(--av4); }

.member-info {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
}

.member-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-main);
}

.member-status {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 99px;
}

.member-status.done {
  background: var(--done-bg);
  color: var(--done-text);
}

.member-status.reading {
  background: var(--reading-bg);
  color: var(--reading-text);
}

.member-status.behind {
  background: var(--behind-bg);
  color: var(--behind-text);
}

.member-pages {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
}

.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--footer-bg);
  border-radius: 10px;
  padding: 10px 14px;
  border: 1px solid var(--border);
}

.next-meet {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-main);
}

.genre-tag {
  font-size: 11px;
  font-weight: 700;
  background: var(--tag-bg);
  color: var(--tag-text);
  padding: 3px 10px;
  border-radius: 99px;
}
